import React from "react";
import { Routes, Route, Link, useNavigate } from "react-router-dom";
import "./AdminPanel.css";
import axios from "axios";

const Panel = () => {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <div className="flex">
        <aside className="w-64 bg-white shadow h-screen p-4">
          <h2 className="text-xl font-bold mb-6">YÜZAG Panel</h2>
          <nav className="space-y-2">
            <Link to="/admin" className="block text-gray-700 hover:text-blue-600">Dashboard</Link>

            <button 
              onClick={handleLogout}
              className="block w-full text-left text-gray-700 hover:text-red-600"
            >
              Çıkış Yap
            </button>
          </nav>
        </aside>

        <main className="flex-1 p-6">
          <Routes>
            <Route path="" element={<Dashboard />} />
          </Routes>
        </main>
      </div>
    </div>
  );
};

const Dashboard = () => {
  const [count, setCount] = React.useState(0);

  React.useEffect(() => {
    axios.get(`${process.env.REACT_APP_API_BASE_URL}/members`).then(res => {
      const approvedMembers = res.data.members?.filter(member => member.status === "Onaylandı") || [];
      setCount(approvedMembers.length);
    });
  }, []);

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-bold">Dashboard</h1>
      <div className="bg-white p-4 rounded shadow">
        <p className="text-gray-600">Toplam Üye Sayısı: <strong>{count}</strong></p>
      </div>
    </div>
  );
};

export default Panel;
