import React, { useRef, useState } from "react";
import emailjs from "@emailjs/browser";

export default function Contact() {
  const formRef = useRef();
  const [status, setStatus] = useState(null); // "success" | "error"

  const handleSubmit = (e) => {
    e.preventDefault();
    setStatus(null);

    // reCAPTCHA geçici olarak devre dışı bırakıldı
    emailjs
      .sendForm(
        process.env.REACT_APP_EMAILJS_SERVICE_ID,
        process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
        formRef.current,
        process.env.REACT_APP_EMAILJS_PUBLIC_KEY
      )
      .then(
        () => {
          setStatus("success");
          formRef.current.reset();
        },
        () => setStatus("error")
      );
  };

  return (
    <div className="container-contact">
 {/*    <section className="testimonial-section section-padding section-bg">
      <div className="container">
        <div className="row">
          <div className="col-lg-8 col-12 mx-auto">
            <h2 className="mb-lg-3">İletişim</h2>


          </div>
        </div>
      </div>
    </section>
*/}
    <section className="contact-section section-padding" id="contact-section">
      <div className="container">
        <div className="row">


          <div className="col-lg-6 col-12">
            
            <div className="contact-info-wrap">
            <h2>İletişime Geç</h2>
            <div className="contact-image-wrap d-flex flex-wrap">

                            </div>
              <div className="contact-info-item mb-3">
                <i className="bi-geo-alt-fill me-2 text-primary"></i>
                <span>Beylikdüzü, İstanbul</span>
              </div>
              {/*<div className="contact-info-item mb-3">
                <i className="bi-telephone-fill me-2 text-primary"></i>
                <span>+47 120 240 9600</span>
              </div> */}
              <div className="contact-info-item mb-3">
                <i className="bi-envelope-fill me-2 text-primary"></i>
                <span>info@yuzag.org</span>
              </div>
              <div className="contact-info-item">
                <i className="bi-clock-fill me-2 text-primary"></i>
                <span>Pazartesi - Cuma: 09:00 - 17:00</span>
              </div>
            </div>
          </div>

          <div className="col-lg-6 col-12">
            <form
              ref={formRef}
              onSubmit={handleSubmit}
              className="custom-form contact-form"
              method="POST"
            >
              <h2>İletişim Formu</h2>

              <p className="mb-4">Veya, mail gönderin:
                  <a href="#">info@yuzag.org</a>
              </p>
              <div className="row">
                <div className="col-lg-6 col-md-6 col-12">
                  <input
                    type="text"
                    name="name"
                    className="form-control"
                    placeholder="Adınız"
                    required
                  />
                </div>

                <div className="col-lg-6 col-md-6 col-12">
                  <input
                    type="text"
                    name="surname"
                    className="form-control"
                    placeholder="Soyadınız"
                    required
                  />
                </div>

                <div className="col-lg-6 col-md-6 col-12">
                  <input
                    type="email"
                    name="email"
                    className="form-control"
                    placeholder="E-posta Adresiniz"
                    required
                  />
                </div>

                <div className="col-lg-6 col-md-6 col-12">
                  <input
                    type="tel"
                    name="phone"
                    className="form-control"
                    placeholder="Telefon Numaranız"
                    required
                  />
                </div>

                <div className="col-12">
                  <textarea
                    name="message"
                    rows="5"
                    className="form-control"
                    placeholder="Mesajınız"
                    required
                  ></textarea>
                </div>

                {/* KVKK Onayı */}
                <div className="col-12">
                  <label>
                    <input type="checkbox" name="kvkk" required />{' '}
                    KVKK Aydınlatma Metni’ni{' '}
                    <a
                          href="/assets/docs/YUZAG_KVKK_Aydinlatma_Metni.pdf" 
                          className="text-primary"
             
                          rel="noopener noreferrer"
                          download="YUZAG_KVKK_Aydinlatma_Metni.pdf"
                        >
                          okudum
                        </a>{' '}
                    ve kişisel verilerimin işlenmesine onay veriyorum.
                  </label>
                  
                </div>

                {/* Honeypot (görünmez alan) */}
                {/* <input
                  type="text"
                  name="website"
                  style={{ display: "none" }}
                  tabIndex="-1"
                  autoComplete="off"
                />*/}

                {/* reCAPTCHA (geçici olarak yorum satırı) */}
                {/**
                <ReCAPTCHA
                  sitekey={process.env.REACT_APP_RECAPTCHA_KEY}
                  onChange={(token) => setRecaptchaToken(token)}
                />
                **/}

                <div className="col-12">
                  <button type="submit" className="form-control">
                    Gönder
                  </button>
                </div>

                {/* Durum Mesajı */}
                <div className="col-12">
                  {status === "success" && (
                    <p className="text-green-600 mt-4">
                       Mesajınız başarıyla gönderildi!
                    </p>
                  )}
                  {status === "error" && (
                    <p className="text-red-600 mt-4">
                      ⚠️ İşlem başarısız. Lütfen tekrar deneyin.
                    </p>
                  )}
                </div>
              </div>
            </form>
          </div>
        </div>
      </div>
    </section>
    </div>
  );
}