import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  const [isSticky, setIsSticky] = useState(false);
  const [isOpen, setIsOpen] = useState(false);                 // navbar collapse (hamburger)
  const [openMenu, setOpenMenu] = useState(null);              // 'about' | 'works' | null

  useEffect(() => {
    const onScroll = () => setIsSticky(window.scrollY > 50);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Dışarı tıklayınca dropdown ve menüyü kapat (mobil UX)
  useEffect(() => {
    const onDocClick = (e) => {
      const nav = document.getElementById('main-navbar');
      if (nav && !nav.contains(e.target)) {
        setOpenMenu(null);
        setIsOpen(false);
      }
    };
    document.addEventListener('click', onDocClick);
    return () => document.removeEventListener('click', onDocClick);
  }, []);

  const toggleNavbar = () => setIsOpen(prev => !prev);

  const toggleDropdown = (key) => {
    setOpenMenu(prev => (prev === key ? null : key));
  };

  const closeAll = () => {
    setOpenMenu(null);
    setIsOpen(false);
  };

  const handleScrollToContact = () => {
    document.getElementById('contact-section')?.scrollIntoView({ behavior: 'smooth' });
    closeAll();
  };

  return (
    <nav
      id="main-navbar"
      className={`navbar navbar-expand-lg navbar-light bg-light shadow-lg ${isSticky ? 'sticky-top' : ''}`}
    >
      <div className="container-fluid px-4">
        <Link className="navbar-brand d-flex align-items-center" to="/" onClick={closeAll}>
          <img
            src="/assets/images/logo.png"
            className="img-fluid me-2"
            style={{ maxHeight: '40px' }}
            alt="YÜZAG"
          />
          <span
            className="fw-semibold"
            style={{
              color: '#007C89',
              fontSize: '14px',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              maxWidth: '250px',
            }}
          >
            Yüzyılın Aile ve Gençlik Hareketi
          </span>
        </Link>

        {/* HAMBURGER - tamamen React yönetiyor */}
        <button
          className={`navbar-toggler ${isOpen ? '' : 'collapsed'}`}
          type="button"
          aria-controls="navbarSupportedContent"
          aria-expanded={isOpen ? 'true' : 'false'}   // KindHeart CSS bu attribute’a bakıp X/hamburger yapıyor
          aria-label="Toggle navigation"
          onClick={toggleNavbar}
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        {/* Collapse alanı */}
        <div className={`collapse navbar-collapse mt-3 mt-lg-0 ${isOpen ? 'show' : ''}`} id="navbarSupportedContent">
          <ul className="navbar-nav ms-auto">

            {/* Biz Kimiz? */}
            <li className="nav-item dropdown dd-center">
              <button
                className="nav-link dropdown-toggle btn btn-link"
                type="button"
                aria-expanded={openMenu === 'hakkimizda' ? 'true' : 'false'}
                onClick={() => toggleDropdown('hakkimizda')}
                style={{ textDecoration: 'none' }}
              >
                Biz Kimiz?
              </button>
              <ul className={`dropdown-menu  ${openMenu === 'hakkimizda' ? 'show' : ''}`}>
                <li><Link className="dropdown-item" to="/hakkimizda" onClick={closeAll}>Hakkımızda</Link></li>
                <li><Link className="dropdown-item" to="/misyonumuz" onClick={closeAll}>Misyonumuz</Link></li>
                <li><Link className="dropdown-item" to="/vizyonumuz" onClick={closeAll}>Vizyonumuz</Link></li>
              </ul>
            </li>

            {/* Projelerimiz */}
            <li className="nav-item dropdown">
              <button
                className="nav-link dropdown-toggle btn btn-link"
                type="button"
                aria-expanded={openMenu === 'projelerimiz' ? 'true' : 'false'}
                onClick={() => toggleDropdown('projelerimiz')}
                style={{ textDecoration: 'none' }}
              >
                Projelerimiz
              </button>
              <ul className={`dropdown-menu ${openMenu === 'projelerimiz' ? 'show' : ''}`}>
                <li><Link className="dropdown-item" to="/genis-aile" onClick={closeAll}>Geniş Aile</Link></li>

              </ul>
            </li>

            <li className="nav-item">
              <Link className="nav-link" to="/uyelik" onClick={closeAll}>Üye Ol</Link>
            </li>

            <li className="nav-item">
              <button className="nav-link btn btn-link" onClick={handleScrollToContact}>İletişim</button>
            </li>

            <li className="nav-item ms-3">
              <Link className="nav-link custom-btn custom-border-btn btn" to="/bagis" onClick={closeAll}>
                Bağış Yap
              </Link>
            </li>

          </ul>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
